"use strict";
const assert = require("assert");
const { add, subtract, multiply, divide, power } = require("./calc");

let passed = 0;
let failed = 0;

function test(name, fn) {
  try {
    fn();
    console.log(`  PASS  ${name}`);
    passed++;
  } catch (err) {
    console.log(`  FAIL  ${name}: ${err.message}`);
    failed++;
  }
}

// add
test("add: 2+3=5", () => assert.strictEqual(add(2, 3), 5));
test("add: negative", () => assert.strictEqual(add(-1, 1), 0));

// subtract
test("subtract: 5-3=2", () => assert.strictEqual(subtract(5, 3), 2));
test("subtract: negative result", () => assert.strictEqual(subtract(1, 4), -3));

// multiply
test("multiply: 3*4=12", () => assert.strictEqual(multiply(3, 4), 12));
test("multiply: by zero", () => assert.strictEqual(multiply(7, 0), 0));

// divide
test("divide: 10/2=5", () => assert.strictEqual(divide(10, 2), 5));
test("divide: by zero returns null", () => assert.strictEqual(divide(5, 0), null));

// power
test("power: 2^3=8", () => assert.strictEqual(power(2, 3), 8));
test("power: any^0=1", () => assert.strictEqual(power(7, 0), 1));

console.log(`\n${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
